#!/usr/bin/env bash
# Chapitre « Le droit à l'image » (partie Légal et RGPD, désormais rédigée) + sommaire.
# Prérequis : apply-signature-demandes.sh.
# Usage (racine du repo) : bash apply-docs-droit-image.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/legal/droit-a-l-image.mdx" 2>/dev/null | grep -qF "title: \"Le droit à l'image\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "export async function replySignature" "packages/backend/src/modules/tickets/tickets.service.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-signature-demandes.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/legal/droit-a-l-image.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Le droit à l'image\"" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/legal"
base64 -d > "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" <<'B64'
